import re
hunks = []
cur = None
for line in open('/tmp/rt_v1v2.diff', encoding='utf-8'):
    if line.startswith('@@'):
        m = re.match(r'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
        cur = {'v1': (int(m.group(1)), int(m.group(2) or 1)), 'v2': (int(m.group(3)), int(m.group(4) or 1)), 'minus': [], 'plus': []}
        hunks.append(cur)
    elif cur is not None and line.startswith('-') and not line.startswith('---'):
        cur['minus'].append(line[1:])
    elif cur is not None and line.startswith('+') and not line.startswith('+++'):
        cur['plus'].append(line[1:])
idre = re.compile(r'\b(D-\d|S-\d+|FD-[A-Z0-9]+|RT4-CERTAIN|R-X3|H[12]-[A-Z]|L-INT|L-SPREAD|C-CEIL|C-BR1|IR-[123]|BR-1|E[12])\b')
v2 = open('/workspace/experiments/EXP-NISTBIN-451dfa/specification.yaml', encoding='utf-8').read().split('\n')
def key_at(n):
    for i in range(n - 1, -1, -1):
        s = v2[i]
        m = re.match(r'^(\s*)([A-Za-z_][A-Za-z0-9_\-]*):', s)
        if m and len(m.group(1)) <= 4:
            return m.group(2)
    return '?'
for i, h in enumerate(hunks, 1):
    plus = ''.join(h['plus'])
    ids = sorted(set(idre.findall(plus)))
    marked = 'VERSION 2' in plus or 'version 2' in plus.lower()
    print(f"{i:2d} v1 {h['v1'][0]}+{h['v1'][1]} v2 {h['v2'][0]}+{h['v2'][1]} -{len(h['minus'])}/+{len(h['plus'])} key={key_at(h['v2'][0])} marked={'Y' if marked else 'N'} ids={','.join(ids)}")

