import re
exec(open('/tmp/rt_hunks.py').read().split('idre =')[0])
v2 = open('/workspace/experiments/EXP-NISTBIN-451dfa/specification.yaml', encoding='utf-8').read().split('\n')
targets = ['C-RHOCONV', 'C-IDENT', 'C-ARG', 'C-XDEG', 'stage_order_enforcement', 'out_of_scope', 'budget', 'stopping_rules', 'required_artifacts', 'frozen_c2_fixture', 'fixture_target', 'model', 'target', 'tolerance', 'tolerance_basis', 'pass_rule', 'gate']
def block(i):
    ind = len(v2[i]) - len(v2[i].lstrip())
    lead = v2[i].lstrip().startswith('- ')
    j = i + 1
    while j < len(v2):
        s = v2[j]
        if s.strip():
            k = len(s) - len(s.lstrip())
            if k < ind or (k == ind and not lead) or (k == ind and lead and s.lstrip().startswith('- ')):
                break
        j += 1
    return i + 1, j
for t in targets:
    for i, s in enumerate(v2):
        if re.match(r'^\s*(- )?(id: )?' + re.escape(t) + r'(:|\s*$)', s):
            a, b = block(i)
            hit = [n for n, h in enumerate(hunks, 1) if h['v2'][1] > 0 and not (h['v2'][0] + h['v2'][1] - 1 < a or h['v2'][0] > b)]
            print(f'{t:24s} v2 lines {a}-{b} hunks={hit}')
